'use strict';
const $=s=>document.querySelector(s), KEY='shike-v1';
const DEFAULT={configured:false,diet:'all',allergens:[],hard:[],soft:[],cuisines:[],budget:150,mode:'both'};
const ALLERGENS=['蛋','奶','大豆','麩質','花生','堅果','芝麻','魚','甲殼類'];
const CUISINES=['台式','日式','西式','韓式','南洋'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const split=s=>[...new Set(String(s).split(/[,，、\n]/).map(x=>x.trim()).filter(Boolean))];
const dietName={all:'無特殊飲食方式',vegan:'全素',vegetarian:'蛋奶素'};
let storageIssue=false;
function read(){try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(!x)return null;if(!x.profile||!Array.isArray(x.favorites)||!Array.isArray(x.blocked)||!Array.isArray(x.history))throw Error();return x}catch(e){storageIssue=true;return null}}
const old=read();
let state={profile:{...DEFAULT,...old?.profile},favorites:old?.favorites||[],blocked:old?.blocked||[],history:old?.history||[]};
for(const k of ['allergens','hard','soft','cuisines'])if(!Array.isArray(state.profile[k]))state.profile[k]=[];
let query={slot:'午餐',mode:state.profile.mode,budget:state.profile.budget,time:30,type:'不限',required:[]};
let batch=[],seen=new Set(),roundKey='',libraryTab='favorites',toastTimer;
const knownFoods=new Set([...MEALS.flatMap(m=>m.ingredients),...Object.keys(FOOD_ALIASES)]);
const matches=(m,term)=>{const list=FOOD_ALIASES[term]||[term];return m.ingredients.some(i=>list.includes(i))};
function cost(m,q=query){return q.mode==='home'?m.cost:q.mode==='out'?m.outCost:Math.min(m.cost,m.outCost)}
function viableModes(m,q){const modes=[];if(q.mode!=='out'&&m.cost<=q.budget&&m.time<=q.time)modes.push('home');if(q.mode!=='home'&&m.outCost<=q.budget)modes.push('out');return modes}
function evaluate(meals,profile,q,blocked=[],history=[]){
 const required=q.required||[];
 const ingredientAllowed=i=>!profile.hard.some(t=>(FOOD_ALIASES[t]||[t]).includes(i))&&!profile.allergens.some(a=>(FOOD_RULES.allergens[i]||[]).includes(a))&&!(profile.diet!=='all'&&FOOD_RULES.animal.includes(i))&&!(profile.diet==='vegan'&&['雞蛋','牛奶','起司','原味優格','蜂蜜'].includes(i));
 const conflicts=required.filter(t=>!(FOOD_ALIASES[t]||[t]).some(ingredientAllowed));
 const missingRequired=required.filter(t=>!meals.some(m=>matches(m,t)));
 const unknown=profile.hard.filter(t=>!knownFoods.has(t));
 if(unknown.length)return{eligible:[],unknown,hardCount:0,conflicts,missingRequired,ingredientCount:0};
 const strict=meals.filter(m=>!blocked.includes(m.id)&&(!(required.length||profile.hard.length||profile.allergens.length||profile.diet!=='all')||m.complete)&&!(profile.diet==='vegan'&&m.diet!=='vegan')&&!(profile.diet==='vegetarian'&&m.diet==='all')&&!profile.allergens.some(a=>m.allergens.includes(a))&&!profile.hard.some(t=>matches(m,t)));
 const withIngredients=strict.filter(m=>required.every(t=>matches(m,t)));
 const eligible=withIngredients.filter(m=>m.slots.includes(q.slot)&&(q.type==='不限'||m.type===q.type)&&viableModes(m,q).length).map(m=>({...m,score:(profile.cuisines.includes(m.cuisine)?6:0)-profile.soft.filter(t=>matches(m,t)).length*5-history.slice(0,7).filter(h=>h.id===m.id).length*4})).sort((a,b)=>b.score-a.score);
 return{eligible,unknown,hardCount:strict.length,conflicts,missingRequired,ingredientCount:withIngredients.length};
}
window.MealEngine={evaluate,viableModes,matches};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageIssue=false;return true}catch(e){storageIssue=true;toast('此瀏覽器無法儲存資料，關閉後設定可能遺失。');return false}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function current(){return evaluate(MEALS,state.profile,query,state.blocked,state.history)}
function recommend(reset=false){const signature=JSON.stringify([query,state.profile,state.blocked]);if(reset||roundKey!==signature){seen.clear();roundKey=signature}const pool=current().eligible.filter(m=>!seen.has(m.id));batch=[];let remaining=[...pool];while(batch.length<3&&remaining.length){const used=new Set(batch.map(m=>m.type));const options=remaining.filter(m=>!used.has(m.type));const choices=options.length?options:remaining;const top=choices[0].score;const candidates=choices.filter(m=>m.score>=top-1).slice(0,8);const chosen=candidates[Math.floor(Math.random()*candidates.length)];batch.push(chosen);seen.add(chosen.id);remaining=remaining.filter(m=>m.id!==chosen.id)}return batch}
function tag(text,hard=false){return `<span class="chip ${hard?'hard':''}">${esc(text)}</span>`}
function profileTags(){const p=state.profile;return[tag(dietName[p.diet]||dietName.all),...p.allergens.map(a=>tag('避開'+a,true)),...p.hard.map(t=>tag('不吃'+t,true))].join('')}
function field(id,label,options,value){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`}
function heading(title,subtitle){return `<div class="saved-heading"><p class="eyebrow">MAKE ROOM FOR A GOOD MEAL</p><h1>${title}</h1><p class="muted">${subtitle}</p></div>`}
function render(){const page=(location.hash|| (state.profile.configured?'#today':'#settings')).slice(1);document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(page==='settings')renderSettings();else if(page==='saved')renderSaved();else renderToday();if(storageIssue)$('#main').insertAdjacentHTML('afterbegin','<p class="notice" role="alert">本機資料無法讀取或儲存。你仍可使用推薦，但請確認瀏覽器允許網站儲存資料。</p>')}
function renderToday(){
 if(!roundKey)recommend(true);
 $('#main').innerHTML=`<section class="page-heading"><div><p class="eyebrow">A LITTLE LESS INDECISION</p><h1>把選擇留給我們，<br>把這餐留給自己。</h1><p class="muted">從你的飲食習慣出發，找點想吃的。</p></div><div class="intro-note"><img src="bowl.jpg" alt="毛豆、酪梨與蔬菜組成的彩色飯碗" width="700" height="1050"><span>今天的好好吃飯提案</span><strong>吃得合適，<br>也吃得開心。</strong></div></section>
 ${!state.profile.configured?'<div class="notice">尚未設定飲食限制，目前以不限飲食推薦。<a class="link-button" href="#settings">先設定我的飲食條件</a></div>':''}
 <section class="panel"><div class="section-top"><div><h2><span class="number">01</span>這餐想怎麼吃？</h2><p>必要限制始終生效，偏好只影響排序。</p></div><a class="link-button" href="#settings">編輯設定</a></div><div class="chips">${profileTags()}</div><form id="query-form"><div class="grid-fields">
 ${field('slot','餐別',['早餐','午餐','晚餐','點心'],query.slot)}${field('mode','用餐方式',[['both','自煮與外食皆可'],['home','自己煮'],['out','外食']],query.mode)}<div class="field"><label for="budget">預算上限（NT$）</label><input id="budget" name="budget" type="number" min="1" max="10000" required value="${query.budget}"></div>${field('time','自煮時間',[[10,'10 分鐘內'],[15,'15 分鐘內'],[20,'20 分鐘內'],[30,'30 分鐘內'],[45,'45 分鐘內'],[120,'不限']],query.time)}${field('type','想吃的類型',['不限','飯','麵','湯','輕食'],query.type)}</div><div class="required-foods"><div class="field"><label for="required-foods">這餐一定要有的食材 <span class="optional">選填</span></label><div class="required-input"><input id="required-foods" name="required" type="text" maxlength="250" value="${esc((query.required||[]).join('、'))}" placeholder="例如：番茄、雞蛋" aria-describedby="required-help"><button class="btn" type="button" id="clear-required">清空</button></div><p id="required-help" class="helper">清冰箱，或剛好想吃某種食材？以逗號分隔，多項必須全部包含；留空則不限。按「幫我想這餐」套用，不會改動長期飲食設定。</p></div></div><div class="action-row"><button class="btn primary" type="submit">幫我想這餐</button><span class="helper">${MEALS.length} 道料理靈感 · 外食不套用自煮時間</span></div></form></section><section id="results" aria-live="polite"></section>`;
 $('#query-form').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.currentTarget);query={slot:form.get('slot'),mode:form.get('mode'),budget:Number(form.get('budget')),time:Number(form.get('time')||query.time),type:form.get('type'),required:split(form.get('required')||'')};recommend(true);renderResults()});
 $('#clear-required').addEventListener('click',()=>{$('#required-foods').value='';$('#required-foods').focus()});
 $('#mode').addEventListener('change',e=>{$('#time').disabled=e.target.value==='out'});$('#time').disabled=query.mode==='out';renderResults();
}
function reason(m){const p=state.profile;const r=[];if(query.required?.length)r.push('包含 '+query.required.join('、'));if(p.diet!=='all')r.push('符合'+dietName[p.diet]+'設定');if(p.allergens.length||p.hard.length)r.push('已排除指定食材');if(p.cuisines.includes(m.cuisine))r.push('你偏好的'+m.cuisine+'料理');if(!r.length)r.push('符合這餐預算與用餐條件');return esc(r.join(' · '))}
function card(m,index=0,context='today',date=''){const modes=viableModes(m,query);const label=context==='today'?(modes.length===2?'自煮 / 外食':modes[0]==='home'?'自己煮':'外食點餐靈感'):'料理收藏';const price=context==='today'?(modes.includes('home')?m.cost:m.outCost):m.cost;return `<article class="food-card"><div class="card-top tone${index%3}"><span class="category">${m.cuisine} · ${m.type} / ${label}</span><span class="card-index">${String(index+1).padStart(2,'0')}</span></div><div class="card-body">${date?`<div class="history-date">${esc(date)}</div>`:''}<h3>${esc(m.name)}</h3><p class="ingredients">${m.ingredients.slice(0,5).map(esc).join('、')}${m.ingredients.length>5?'…':''}</p>${context==='today'?`<p class="reason">✓ ${reason(m)}</p>`:'<p class="reason">'+dietName[m.diet]+'</p>'}<div class="stats"><span>約 NT$${price}${context==='today'&&modes.length===2?' 起':''}</span><span>${context!=='today'||modes.includes('home')?m.time+' 分鐘自煮':'需向店家確認成分'}</span></div><div class="card-actions">${context==='today'?`<button class="btn primary" data-action="choose" data-id="${m.id}">就吃這個</button>`:`<button class="btn primary" data-action="detail" data-id="${m.id}">查看餐點</button>`}<button class="btn icon-btn" data-action="favorite" data-id="${m.id}" aria-label="${state.favorites.includes(m.id)?'取消收藏':'收藏'}${esc(m.name)}" aria-pressed="${state.favorites.includes(m.id)}">${state.favorites.includes(m.id)?'♥':'♡'}</button></div><div class="card-bottom"><button class="link-button" data-action="detail" data-id="${m.id}">${context==='today'?'食材與做法':'完整食材'}</button><button class="link-button" data-action="block" data-id="${m.id}">不想再看到</button></div></div></article>`}
function emptyReason(result){
 const {unknown,hardCount,conflicts,missingRequired,ingredientCount}=result;
 if(unknown.length)return '無法確認這些禁止食材：'+unknown.join('、')+'。請到飲食設定使用已知食材名稱。';
 if(conflicts.length)return '指定的「'+conflicts.join('、')+'」與你的飲食方式、過敏原或禁止食材衝突。請更換這餐必備食材，原有飲食限制仍會保留。';
 if(missingRequired.length)return '目前餐點資料沒有包含「'+missingRequired.join('、')+'」的料理。可改用資料中的食材名稱，或更換這餐必備食材。';
 if(!hardCount)return '目前資料庫沒有通過飲食限制的餐點，或餐點皆已被排除。';
 if(query.required?.length&&!ingredientCount)return '目前沒有通過飲食限制且同時包含「'+query.required.join('、')+'」的餐點。請減少或更換必備食材；不會自動漏掉其中任何一項。';
 return '符合飲食限制'+(query.required?.length?'與必備食材':'')+'的 '+ingredientCount+' 道料理中，沒有同時符合本次餐別、類型、預算與時間的餐點。';
}
function renderResults(){const {eligible,unknown,hardCount,conflicts,missingRequired,ingredientCount}=current();const left=eligible.filter(m=>!seen.has(m.id)).length;$('#results').innerHTML=`<div class="recommend-heading"><div><h2><span class="number">02</span>這餐，試試這些</h2><p class="helper">${eligible.length} 道符合目前條件${eligible.length>0?' · 已看過 '+seen.size+' 道':''}</p></div><button class="btn" id="random" ${!eligible.length?'disabled':''}>幫我選一個</button></div>${query.required?.length?`<div class="chips applied-ingredients" aria-label="已套用的必備食材">${query.required.map(t=>tag('必須有：'+t)).join('')}</div>`:''}${batch.length?`<div class="cards">${batch.map((m,i)=>card(m,i)).join('')}</div><div class="action-row" style="margin-top:22px"><button class="btn" id="more" ${left?'':'disabled'}>換一批（還有 ${left} 道）</button>${!left?'<button class="link-button" id="restart">全部看過了，重新選一輪</button>':''}<span class="helper">${batch.length<3?'剩餘候選不足 3 道，已顯示全部。':'換一批會保留飲食條件，不重複本輪餐點。'}</span></div>`:`<div class="empty"><h3>先調整一點，找到適合的餐點</h3><p class="muted">${esc(emptyReason({unknown,hardCount,conflicts,missingRequired,ingredientCount}))}</p><p class="helper">不會自動放寬過敏原或禁止食材。</p><div class="action-row" style="justify-content:center"><a class="btn" href="#settings">查看飲食設定</a>${!unknown.length?'<button class="btn" id="adjust">調整這餐需求</button>':''}</div></div>`}<p class="helper" style="margin-top:18px">依所列食譜成分篩選；外食實際配料、醬料與共用器具需向店家確認。</p>`;
 $('#more')?.addEventListener('click',()=>{recommend();renderResults()});$('#restart')?.addEventListener('click',()=>{recommend(true);renderResults()});$('#adjust')?.addEventListener('click',()=>$(query.required?.length?'#required-foods':'#budget').focus());$('#random').addEventListener('click',()=>{const eligible=current().eligible;if(!eligible.length)return;const chosen=eligible[Math.floor(Math.random()*Math.min(eligible.length,8))];openDetail(chosen.id,true)});bindActions($('#results'))}
function bindActions(root){root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.id;switch(b.dataset.action){case 'detail':openDetail(id);break;case 'choose':choose(id);break;case 'favorite':{const has=state.favorites.includes(id);state.favorites=has?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();toast(has?'已取消收藏':'已加入我的餐點');render();break}case 'block':state.blocked=[...new Set([...state.blocked,id])];save();recommend(true);toast('已排除此餐點，可在飲食設定中還原');render();break;case 'restore':state.blocked=state.blocked.filter(x=>x!==id);save();roundKey='';render();toast('餐點已還原');break;}}))}
function choose(id){if(!current().eligible.some(m=>m.id===id)){toast('這道餐點已不符合目前條件，請重新推薦。');return}state.history.unshift({id,at:new Date().toISOString()});state.history=state.history.slice(0,100);save();$('#detail').close();const m=MEALS.find(m=>m.id===id);toast('這餐就吃 '+m.name+'！已記錄到近期選擇。');if((location.hash||'#today')==='#today')renderResults()}
function openDetail(id,random=false){const m=MEALS.find(x=>x.id===id);if(!m)return;const allowed=current().eligible.some(x=>x.id===id);const modes=viableModes(m,query);const d=$('#detail');d.innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${random?'今天幫你選了這一道':'MEAL DETAILS'}</p><h2>${esc(m.name)}</h2></div><button class="btn" id="close-dialog" aria-label="關閉餐點詳情">×</button></div><p class="muted">${m.cuisine} · ${dietName[m.diet]} · 自煮約 ${m.time} 分鐘</p><div class="chips">${tag('自煮約 NT$'+m.cost)}${tag('外食約 NT$'+m.outCost)}</div><h3 style="margin-top:25px">完整食材</h3><p>${m.ingredients.map(esc).join('、')}</p><p class="helper">已標記過敏原：${m.allergens.length?m.allergens.join('、'):'所列材料無上述 9 類過敏原標記'}。未標記不代表適合所有過敏情況。</p><h3 style="margin-top:24px">簡要做法</h3><ol>${m.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="helper">時間為簡易備料與烹調估算；熟飯、熟豆類及即食食材需事先備妥。</p><div class="notice">${m.note}${m.ingredients.some(x=>['純素小麥吐司','醬油','味噌','燕麥'].includes(x))?' 吐司、醬料與燕麥的不同品牌可能含額外過敏原；本版麩質限制會排除一般燕麥與味噌。':''}</div>${allowed?`<p class="helper">目前符合的方式：${modes.map(x=>x==='home'?'自己煮':'外食點餐構想').join('、')}</p><button class="btn primary" id="confirm-meal">${random?'好，就吃這個':'就吃這個'}</button>`:'<p class="notice">這道餐點不符合目前的飲食限制或當餐條件，僅供查看。</p>'}`;$('#close-dialog').onclick=()=>d.close();$('#confirm-meal')?.addEventListener('click',()=>choose(id));if(!d.open)d.showModal();}
function checks(name,values,chosen){return `<div class="checks">${values.map(v=>`<label class="check"><input type="checkbox" name="${name}" value="${esc(v)}" ${chosen.includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</div>`}
function renderSettings(){const p=state.profile;$('#main').innerHTML=heading(p.configured?'你的飲食，有自己的原則。':'先認識你的飲食習慣。','設定一次，每次選餐都替你記得。之後隨時可以修改。')+`<form id="settings-form" class="panel"><div class="section-top"><h2><span class="number">01</span>必須遵守的條件</h2><span class="chip hard">不會自動放寬</span></div><div class="settings-grid">${field('diet','飲食方式',[['all','無特殊限制'],['vegan','全素（不含肉、蛋、奶）'],['vegetarian','蛋奶素（不含肉與海鮮）']],p.diet)}<div class="field"><label for="hard">禁止食材（以逗號分隔）</label><input id="hard" name="hard" type="text" maxlength="250" value="${esc(p.hard.join('、'))}" placeholder="例如：牛肉、香菜、五辛"><span class="helper">可填牛肉、豬肉、海鮮、菇、蒜、香菜等；未知名稱會停止推薦。</span></div></div><div class="form-section"><h3>需要避開的過敏原</h3><p class="helper">依餐點列出的食材篩選，加工食品仍須核對成分與交叉接觸資訊。</p>${checks('allergens',ALLERGENS,p.allergens)}</div><div class="form-section"><h2><span class="number">02</span>你的喜好</h2><p class="helper">影響推薦順序，不會凌駕必要限制。</p><div class="field"><label for="soft">不太喜歡，但不必完全排除</label><input id="soft" name="soft" type="text" maxlength="250" value="${esc(p.soft.join('、'))}" placeholder="例如：洋蔥、番茄"></div><p class="small-title" style="margin-top:18px">喜歡的料理類型</p>${checks('cuisines',CUISINES,p.cuisines)}</div><div class="form-section"><h2><span class="number">03</span>平常的用餐方式</h2><div class="settings-grid" style="margin-top:20px"><div class="field"><label for="default-budget">每餐預算上限（NT$）</label><input id="default-budget" name="budget" type="number" required min="1" max="10000" value="${p.budget}"></div>${field('default-mode','預設用餐方式',[['both','自煮與外食皆可'],['home','自己煮'],['out','外食']],p.mode)}</div></div><div class="notice">資料只保存在這個瀏覽器，不需註冊。不同裝置不會同步；清除瀏覽器資料會移除設定與紀錄。</div><div class="action-row"><button class="btn primary" type="submit">儲存設定，開始選餐</button>${!p.configured?'<button class="link-button" type="button" id="skip">先以不限飲食試用</button>':''}</div><p id="settings-message" role="status" class="helper"></p></form><section class="panel"><h2>已排除的餐點</h2><p class="helper">點選還原後，符合條件時就會再次出現在推薦中。</p><div class="block-list">${state.blocked.length?state.blocked.map(id=>{const m=MEALS.find(m=>m.id===id);return m?`<button class="btn" data-action="restore" data-id="${id}">${esc(m.name)} · 還原</button>`:''}).join(''):'<span class="muted">目前沒有排除的餐點。</span>'}</div></section><section class="panel"><div class="section-top"><div><h2>本機資料</h2><p>清除飲食設定、收藏、排除清單與近期選擇。</p></div><button id="clear-data" class="btn danger" type="button">清除資料</button></div></section>`;
 $('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const profile={configured:true,diet:f.get('diet'),allergens:f.getAll('allergens'),hard:split(f.get('hard')),soft:split(f.get('soft')),cuisines:f.getAll('cuisines'),budget:Number(f.get('budget')),mode:f.get('default-mode')};const unknown=profile.hard.filter(t=>!knownFoods.has(t));state.profile=profile;query={...query,budget:profile.budget,mode:profile.mode};save();roundKey='';if(unknown.length){$('#settings-message').textContent='設定已套用，但無法確認「'+unknown.join('、')+'」。推薦會暫停，請修改名稱。';$('#hard').focus();return}location.hash='today';toast('飲食設定已套用')};
 $('#skip')?.addEventListener('click',()=>{location.hash='today'});$('#clear-data').onclick=()=>{const d=$('#detail');d.innerHTML='<h2>清除這個裝置的所有資料？</h2><p class="muted">飲食設定、收藏、近期選擇與排除清單都會移除，無法復原。</p><div class="action-row"><button class="btn" id="cancel-clear">保留資料</button><button class="btn danger" id="confirm-clear">確定清除</button></div>';$('#cancel-clear').onclick=()=>d.close();$('#confirm-clear').onclick=()=>{try{localStorage.removeItem(KEY);storageIssue=false}catch(e){toast('無法移除儲存資料，請使用瀏覽器的網站資料設定。');return}state={profile:{...DEFAULT,allergens:[],hard:[],soft:[],cuisines:[]},favorites:[],blocked:[],history:[]};query={slot:'午餐',mode:'both',budget:150,time:30,type:'不限',required:[]};roundKey='';seen.clear();batch=[];d.close();render();toast('已清除本機資料')};d.showModal()};bindActions($('#main'));
}
function renderSaved(){const favorite=libraryTab==='favorites';const records=favorite?state.favorites.map(id=>({id})):state.history;const items=records.map(r=>({...r,meal:MEALS.find(m=>m.id===r.id)})).filter(r=>r.meal);$('#main').innerHTML=heading('那些想再吃一次的餐點。','收藏喜歡的，記得吃過的，下次就少一點猶豫。')+`<div class="tabs" role="tablist" aria-label="我的餐點分類"><button class="btn" role="tab" aria-selected="${favorite}" id="tab-favorites">收藏餐點 ${state.favorites.length}</button><button class="btn" role="tab" aria-selected="${!favorite}" id="tab-history">近期選擇 ${state.history.length}</button></div><p class="helper">${favorite?'收藏保留完整清單；餐點若不符合目前條件，詳情中會提示。':'這裡記錄你選擇的餐點，不代表已實際食用。推薦會降低最近 7 次選擇的優先度。'}</p><div role="tabpanel">${items.length?`<div class="cards">${items.map((r,i)=>card(r.meal,i,'saved',r.at?new Date(r.at).toLocaleString('zh-TW',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}):'')).join('')}</div>`:`<div class="empty"><h3>${favorite?'把喜歡的餐點留在這裡':'從這餐開始，留下你的選擇'}</h3><p class="muted">${favorite?'在推薦餐點按下愛心，下次更快找到。':'選擇「就吃這個」後，這裡就會出現紀錄。'}</p><a href="#today" class="btn primary">去選這餐</a></div>`}</div>`;$('#tab-favorites').onclick=()=>{libraryTab='favorites';renderSaved()};$('#tab-history').onclick=()=>{libraryTab='history';renderSaved()};bindActions($('#main'))}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
render();
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'recommend_meals',title:'推薦符合目前條件的餐點',description:'依目前已儲存的飲食限制與當餐條件開始一輪推薦，更新畫面但不記錄用餐選擇。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('只接受空物件');recommend(true);if(location.hash!=='#today')location.hash='today';renderToday();return{meals:batch.map(m=>({id:m.id,name:m.name,ingredients:m.ingredients})),eligibleCount:current().eligible.length}}},{signal:controller.signal})).catch(()=>{})}catch(e){}}
